#!/usr/bin/env python3
# Clean synthetic exporter: writes only the live table binding.

from pathlib import Path

DEFAULT_OUTPUT = Path('proof/corpus/Iota/Generated/Table.lean')


def render():
    return 'import Iota.Source.Bytes'


def main():
    DEFAULT_OUTPUT.write_text(render(), encoding='utf-8')
    return 0


if __name__ == '__main__':
    main()

